import re,unicodedata
from functools import lru_cache
def norm(s):return re.sub('[^a-z0-9]+',' ',unicodedata.normalize('NFKD',s or '').encode('ascii','ignore').decode().lower()).strip()
def slug(s):return norm(s).replace(' ','-')
