ALIASES=[]
for league,groups in GROUPS.items():
 for group in groups.split('|'):
  name,_,aliases=group.partition(':')
  for alias in [name,*aliases.split(',')]:
   if alias:ALIASES.append((norm(alias),name,league))
@lru_cache(maxsize=10000)
def identity(text,baseline=None):
 n=norm(text)
 if re.search(r'\bindependiente (?:de )?medellin\b',n):return "Independiente Medellín","Liga Colombia"
 matches=[(len(a),name,l) for a,name,l in ALIASES if re.search(r'(?<![a-z0-9])'+re.escape(a)+r'(?![a-z0-9])',n) and (baseline!='NBA' or l=='NBA') and (baseline!='Scottish Premiership' or l!='Selecciones') and (l!='Selecciones' or baseline in (None,'Selecciones')) and (l!='NBA' or baseline=='NBA' or re.search(r'\bnba\b|basketball',n))]
 if not matches:return None
 matches.sort(key=lambda x:(x[0],x[2]==baseline),reverse=True)
 if n=='vitoria' and baseline=='Liga Portugal':return 'Vitória de Guimarães','Liga Portugal'
 if n=='cordoba' and baseline=='Liga Argentina':return None
 _,name,l=matches[0];return name,l
